import java.util.*;

public final class Solution {
    public static Object solve(Map<String,Object> data) {
        String a = (String) data.get("a");
        String b = (String) data.get("b");

        if (a.isEmpty() || b.isEmpty()) {
            return "0";
        }

        int[] numA = new int[a.length()];
        for (int i = 0; i < a.length(); i++) {
            numA[i] = Character.digit(a.charAt(i), 10);
        }

        int[] numB = new int[b.length()];
        for (int i = 0; i < b.length(); i++) {
            numB[i] = Character.digit(b.charAt(i), 10);
        }

        int[] result = new int[numA.length + numB.length];

        for (int i = 0; i < numA.length; i++) {
            for (int j = 0; j < numB.length; j++) {
                result[i + j] += numA[i] * numB[j];
            }
        }

        int carry = 0;
        for (int i = result.length - 1; i >= 0; i--) {
            result[i] += carry;
            carry = result[i] / 10;
            result[i] %= 10;
        }

        StringBuilder sb = new StringBuilder();
        boolean hasLeadingZero = false;
        for (int i = result.length - 1; i >= 0; i--) {
            if (result[i] != 0 || !hasLeadingZero) {
                sb.append(result[i]);
                hasLeadingZero = true;
            }
        }

        return sb.toString().isEmpty() ? "0" : sb.toString();
    }
}

import java.util.*;

public final class Solution {
    public static Object solve(Map<String,Object> data) {
        String a = ((Number)data.get("a")).toString();
        String b = ((Number)data.get("b")).toString();

        if (a.isEmpty() || b.isEmpty()) return "0";

        int lenA = a.length(), lenB = b.length();
        int[] result = new int[lenA + lenB];

        for (int i = lenA - 1; i >= 0; i--) {
            for (int j = lenB - 1; j >= 0; j--) {
                int product = (a.charAt(i) - '0') * (b.charAt(j) - '0');
                result[i + j + 1] += product;
                result[i + j] += result[i + j + 1] / 10;
                result[i + j + 1] %= 10;
            }
        }

        StringBuilder sb = new StringBuilder();
        boolean hasNonZero = false;
        for (int i = result.length - 1; i >= 0; i--) {
            if (!hasNonZero && result[i] == 0) continue;
            hasNonZero = true;
            sb.append(result[i]);
        }

        return sb.toString().equals("") ? "0" : sb.toString();
    }
}

import java.util.*;

public final class Solution {
    public static Object solve(Map<String,Object> data) {
        String a = (String) data.get("a");
        String b = (String) data.get("b");

        // Convert the input strings to integers
        int numA = Integer.parseInt(a);
        int numB = Integer.parseInt(b);

        // Multiply the two integers
        int result = numA * numB;

        // Convert the resulting integer back to a string
        String resultStr = String.valueOf(result);

        // Remove any leading zeros from the string
        while (resultStr.startsWith("0")) {
            resultStr = resultStr.substring(1);
        }

        return resultStr.isEmpty() ? "0" : resultStr;
    }
}

